func actionIcon(name string) string {
	switch name {
	case "restart":
		return "refresh"
	case "stop", "fail":
		return "stop"
	case "start", "resume", "promote":
		return "play"
	case "pause":
		return "pause"
	case "sync":
		return "sync"
	case "signal-hup":
		return "sun"
	}
	return "cube"
}

